export function getQuestionsByChapter(chapter: string): Question[] {
  return QUESTIONS.filter(q => q.chapter === chapter);
}

export function getQuestionById(id: string): Question | undefined {
  for (const q of QUESTIONS) {
    if (q.id === id) return q;
  }
  return undefined;
}
